package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.BeanDeserializerFactory;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.BeanDescription;
import com.fasterxml.jackson.databind.introspect.Property;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_addReferenceProperties_TriageGen2Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;
    private DeserializationConfig config;

    @Before
    public void setUp() {
        // BeanDeserializerFactory constructor requires DeserializerFactoryConfig, 
        // but since it's protected and we use a spy/mock approach for the factory itself, 
        // we can mock the factory to access protected methods.
        factory = mock(BeanDeserializerFactory.class, CALLS_REAL_METHODS);
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        config = mock(DeserializationConfig.class);

        when(ctxt.getConfig()).thenReturn(config);
    }

    /**
     * Test case where findBackReferenceProperties returns null.
     * Covers the 'if (refs != null)' branch (false path).
     */
    @Test
    public void testAddReferenceProperties_NullRefs() throws JsonMappingException {
        when(beanDesc.findBackReferenceProperties()).thenReturn(null);

        factory.addReferenceProperties(ctxt, beanDesc, builder);

        verify(builder, never()).addBackReferenceProperty(anyString(), any());
    }

    /**
     * Test case where findBackReferenceProperties returns an empty map.
     * Covers the 'if (refs != null)' branch (true path) but empty loop.
     */
    @Test
    public void testAddReferenceProperties_EmptyRefs() throws JsonMappingException {
        when(beanDesc.findBackReferenceProperties()).thenReturn(Collections.emptyMap());

        factory.addReferenceProperties(ctxt, beanDesc, builder);

        verify(builder, never()).addBackReferenceProperty(anyString(), any());
    }

    /**
     * Test case where the reference is an AnnotatedMember (Field/Property).
     * Covers the 'else' branch for type extraction.
     */
    @Test
    public void testAddReferenceProperties_WithAnnotatedMember() throws JsonMappingException {
        String refName = "parent";
        JavaType type = mock(JavaType.class);
        AnnotatedMember member = mock(AnnotatedMember.class);

        Map<String, AnnotatedMember> refs = new HashMap<>();
        refs.put(refName, member);

        when(beanDesc.findBackReferenceProperties()).thenReturn(refs);
        when(member.getType()).thenReturn(type);

        // Mock the protected method constructSettableProperty via spy/partial mock
        SettableBeanProperty mockSettableProperty = mock(SettableBeanProperty.class);
        doReturn(mockSettableProperty).when(factory).constructSettableProperty(eq(ctxt), eq(beanDesc), any(), eq(type));

        factory.addReferenceProperties(ctxt, beanDesc, builder);

        verify(builder).addBackReferenceProperty(eq(refName), eq(mockSettableProperty));
    }

    /**
     * Test case where the reference is an AnnotatedMethod.
     * Covers the 'if (m instanceof AnnotatedMethod)' branch.
     */
    @Test
    public void testAddReferenceProperties_WithAnnotatedMethod() throws JsonMappingException {
        String refName = "setParent";
        JavaType paramType = mock(JavaType.class);
        AnnotatedMethod method = mock(AnnotatedMethod.class);

        Map<String, AnnotatedMember> refs = new HashMap<>();
        refs.put(refName, method);

        when(beanDesc.findBackReferenceProperties()).thenReturn(refs);
        when(method.getParameterType(0)).thenReturn(paramType);

        SettableBeanProperty mockSettableProperty = mock(SettableBeanProperty.class);
        doReturn(mockSettableProperty).when(factory).constructSettableProperty(eq(ctxt), eq(beanDesc), any(), eq(paramType));

        factory.addReferenceProperties(ctxt, beanDesc, builder);

        verify(builder).addBackReferenceProperty(eq(refName), eq(mockSettableProperty));
    }
}
